import { useCallback, useEffect, useState } from 'react';
import { ArrowLeft, BriefcaseMedical, Copy, Mail, MessageCircle, Phone, Plus, RefreshCw, Search, ShieldCheck, UserRound, UserRoundPlus, X } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { useTenant } from '../../context/TenantContext';
import { createExternalClient, createExternalClientInvitation, getCurrentExternalClientInvitation, listExternalClients, regenerateExternalClientInvitation, revokeExternalClientInvitation, updateExternalClient } from '../../lib/fiteatsyConsultantsApi';
import { buildEmailInvitationUrl, buildWhatsAppInvitationUrl } from '../../lib/externalClientInvitationShare';
import { ExternalClient360 } from './ExternalClient360';

const emptyForm={firstName:'',lastName:'',mobile:'',email:'',dateOfBirth:'',gender:''};
const statusTone={ACTIVE:'bg-emerald-50 text-emerald-700',INACTIVE:'bg-slate-100 text-slate-600',INVITED:'bg-blue-50 text-blue-700',INTAKE_STARTED:'bg-amber-50 text-amber-700',INTAKE_COMPLETED:'bg-violet-50 text-violet-700'};
const Field=({label,...props})=><label className="space-y-1.5 text-sm font-medium text-slate-700"><span>{label}</span><input {...props} className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-900/10"/></label>;

export function ExternalConsultantWorkspace(){
  const {user}=useAuth(); const {tenantName,tenantType,currentMembershipRole}=useTenant();
  const [clients,setClients]=useState([]);const [total,setTotal]=useState(0);const [query,setQuery]=useState('');const [status,setStatus]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [adding,setAdding]=useState(false);const [saving,setSaving]=useState(false);const [form,setForm]=useState(emptyForm);const [selected,setSelected]=useState(null);
  const load=useCallback(async()=>{setLoading(true);setError('');try{const result=await listExternalClients({q:query,status,limit:100});setClients(result.clients||[]);setTotal(result.pagination?.total??0);}catch(e){setError(e.message||'Unable to load clients.');}finally{setLoading(false);}},[query,status]);
  useEffect(()=>{const timer=setTimeout(load,query?250:0);return()=>clearTimeout(timer);},[load,query]);
  const submit=async(e)=>{e.preventDefault();setSaving(true);setError('');try{const result=await createExternalClient({...form,dateOfBirth:form.dateOfBirth||null,gender:form.gender||null});setAdding(false);setForm(emptyForm);await load();setSelected(result.client);}catch(err){setError(err.message||'Unable to add client.');}finally{setSaving(false);}};
  const changeStatus=async(next)=>{if(!selected)return;try{const result=await updateExternalClient(selected.id,{status:next});setSelected(result.client);await load();}catch(e){setError(e.message||'Unable to update client.');}};
  const practiceName=tenantName||user?.name||'My practice';
  return <div className="min-h-screen bg-[#f6f7f8] text-slate-950">
    <header className="border-b border-slate-200 bg-white"><div className="mx-auto flex max-w-7xl items-center justify-between px-6 py-5"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-slate-950 text-white"><BriefcaseMedical size={21}/></div><div><p className="text-xs font-semibold uppercase tracking-[.18em] text-slate-500">External Consultant Workspace</p><h1 className="text-xl font-semibold">{practiceName}</h1></div></div><div className="text-right text-xs text-slate-500"><p>{tenantType?.replaceAll('_',' ')}</p><p>{currentMembershipRole}</p></div></div></header>
    <main className="mx-auto max-w-7xl px-6 py-8">
      {selected?<ExternalClient360 client={selected} onBack={()=>setSelected(null)} onStatus={changeStatus}/>:<>
        <section className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-sm font-medium text-slate-500">Client management</p><h2 className="mt-1 text-3xl font-semibold tracking-tight">Your clients</h2><p className="mt-2 text-sm text-slate-600">{total} active and historical client record{total===1?'':'s'} in this practice.</p></div><button onClick={()=>setAdding(true)} className="inline-flex items-center gap-2 self-start rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white"><Plus size={17}/>Add manually</button></section>
        <section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-col gap-3 border-b border-slate-100 p-4 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-3 text-slate-400" size={18}/><input aria-label="Search clients" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search by name, email, or mobile" className="w-full rounded-xl border border-slate-200 py-2.5 pl-10 pr-3 outline-none focus:border-slate-900"/></label><select aria-label="Filter client status" value={status} onChange={e=>setStatus(e.target.value)} className="rounded-xl border border-slate-200 bg-white px-3 py-2.5"><option value="">All statuses</option>{Object.keys(statusTone).map(v=><option key={v}>{v}</option>)}</select></div>
          {error&&<div role="alert" className="m-4 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
          {loading?<div className="p-12 text-center text-sm text-slate-500">Loading client records…</div>:clients.length===0&&!query&&!status?<ZeroState onAdd={()=>setAdding(true)}/>:clients.length===0?<div className="p-12 text-center text-sm text-slate-500">No clients match your search.</div>:<div className="divide-y divide-slate-100">{clients.map(client=><button key={client.id} onClick={()=>setSelected(client)} className="flex w-full items-center justify-between gap-4 p-5 text-left transition hover:bg-slate-50"><div className="flex min-w-0 items-center gap-4"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-full bg-slate-100 text-slate-600"><UserRound size={20}/></div><div className="min-w-0"><p className="truncate font-semibold">{client.displayName}</p><p className="mt-1 truncate text-sm text-slate-500">{client.email||client.mobile}</p><p className="mt-1 text-xs text-slate-400">{client.invitationStatus?`Invitation ${client.invitationStatus.toLowerCase()}`:'Not invited'}{client.intakeState!=='NOT_STARTED'?` · Intake ${client.intakeCompletionPercent}%`:''}</p></div></div><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${statusTone[client.status]||statusTone.INACTIVE}`}>{client.status.replaceAll('_',' ')}</span></button>)}</div>}
        </section></>}
    </main>{adding&&<CreateDialog form={form} setForm={setForm} saving={saving} error={error} onClose={()=>{setAdding(false);setError('');}} onSubmit={submit}/>}</div>;
}
function ZeroState({onAdd}){return <div className="px-6 py-16 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-slate-100 text-slate-700"><UserRoundPlus size={26}/></div><h3 className="mt-5 text-xl font-semibold">Build your client practice</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-slate-600">Add your first client manually, then generate a secure health-profile invitation.</p><button onClick={onAdd} className="mt-6 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white">Add your first client</button></div>}
function ClientDetail({client,onBack,onStatus}){const {tenantName}=useTenant();const {user}=useAuth();const [invitation,setInvitation]=useState(null);const [shareUrl,setShareUrl]=useState('');const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('');const practiceName=tenantName||user?.name||'My practice';useEffect(()=>{getCurrentExternalClientInvitation(client.id).then(r=>setInvitation(r.invitation)).catch(()=>setInvitation(null));},[client.id]);const issue=async(regenerate=false)=>{setBusy(true);setNotice('');try{const r=await(regenerate?regenerateExternalClientInvitation(client.id):createExternalClientInvitation(client.id));setInvitation(r.invitation);setShareUrl(r.shareUrl);setNotice('Secure invitation generated. Share this link now; it will not be shown again after leaving this page.');}catch(e){setNotice(e.message||'Unable to generate invitation.');}finally{setBusy(false);}};const revoke=async()=>{setBusy(true);try{const r=await revokeExternalClientInvitation(client.id);setInvitation(r.invitation);setShareUrl('');setNotice('Invitation revoked.');}finally{setBusy(false);}};const copy=async()=>{await navigator.clipboard.writeText(shareUrl);setNotice('Invitation link copied.');};const shareInput={clientName:client.displayName,practiceName,shareUrl,email:client.email};return <section><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-slate-600"><ArrowLeft size={17}/>Back to clients</button><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex flex-col justify-between gap-4 sm:flex-row"><div><p className="text-sm text-slate-500">Client record</p><h2 className="mt-1 text-3xl font-semibold">{client.displayName}</h2><p className="mt-2 text-sm text-slate-500">Created from {client.source.replaceAll('_',' ').toLowerCase()}</p></div><select value={client.status} onChange={e=>onStatus(e.target.value)} className="h-11 rounded-xl border border-slate-200 px-3">{Object.keys(statusTone).map(v=><option key={v}>{v}</option>)}</select></div><div className="mt-8 grid gap-4 md:grid-cols-2"><Info icon={Mail} label="Email" value={client.email||'Not provided'}/><Info icon={Phone} label="Mobile" value={client.mobile||'Not provided'}/><Info icon={UserRound} label="Date of birth" value={client.dateOfBirth||'Not provided'}/><Info icon={UserRound} label="Gender" value={client.gender?.replaceAll('_',' ')||'Not provided'}/></div><div className="mt-8 rounded-2xl border border-slate-200 p-5"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 text-emerald-600" size={22}/><div><h3 className="font-semibold">Secure health-profile invitation</h3><p className="mt-1 text-sm text-slate-600">{invitation?`Status: ${invitation.status.toLowerCase().replaceAll('_',' ')}`:'Not invited'}</p></div></div>{notice&&<p role="status" className="mt-4 rounded-xl bg-slate-50 px-3 py-2 text-sm text-slate-700">{notice}</p>}<div className="mt-5 flex flex-wrap gap-2">{!invitation&&<button disabled={busy} onClick={()=>issue(false)} className="rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white">Invite client</button>}{invitation&&['PENDING','OPENED'].includes(invitation.status)&&<><button disabled={busy} onClick={()=>issue(true)} className="inline-flex items-center gap-2 rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold"><RefreshCw size={16}/>Regenerate</button><button disabled={busy} onClick={revoke} className="rounded-xl border border-red-200 px-4 py-2.5 text-sm font-semibold text-red-700">Revoke</button></>}{invitation&&['EXPIRED','REVOKED'].includes(invitation.status)&&<button disabled={busy} onClick={()=>issue(true)} className="rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white">Generate replacement</button>}</div>{shareUrl&&<div className="mt-4 flex flex-wrap gap-2"><button onClick={copy} className="inline-flex items-center gap-2 rounded-xl bg-slate-100 px-3 py-2 text-sm font-semibold"><Copy size={16}/>Copy link</button><a target="_blank" rel="noreferrer" href={buildWhatsAppInvitationUrl(shareInput)} className="inline-flex items-center gap-2 rounded-xl bg-emerald-50 px-3 py-2 text-sm font-semibold text-emerald-700"><MessageCircle size={16}/>WhatsApp</a><a href={buildEmailInvitationUrl(shareInput)} className="inline-flex items-center gap-2 rounded-xl bg-blue-50 px-3 py-2 text-sm font-semibold text-blue-700"><Mail size={16}/>Email</a></div>}</div></div></section>}
function Info({icon:Icon,label,value}){return <div className="rounded-xl bg-slate-50 p-4"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-slate-500"><Icon size={15}/>{label}</div><p className="mt-2 font-medium">{value}</p></div>}
function CreateDialog({form,setForm,saving,error,onClose,onSubmit}){const set=(key)=>e=>setForm(v=>({...v,[key]:e.target.value}));return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/40 p-4"><div role="dialog" aria-modal="true" aria-labelledby="add-client-title" className="w-full max-w-xl rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-slate-100 px-6 py-5"><div><h2 id="add-client-title" className="text-xl font-semibold">Add client manually</h2><p className="mt-1 text-sm text-slate-500">Creates an active record in this practice only.</p></div><button aria-label="Close" onClick={onClose} className="rounded-lg p-2 hover:bg-slate-100"><X size={20}/></button></div><form onSubmit={onSubmit} className="space-y-5 p-6">{error&&<div role="alert" className="rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}<div className="grid gap-4 sm:grid-cols-2"><Field required label="First name" value={form.firstName} onChange={set('firstName')}/><Field required label="Last name" value={form.lastName} onChange={set('lastName')}/><Field label="Mobile" type="tel" value={form.mobile} onChange={set('mobile')}/><Field label="Email" type="email" value={form.email} onChange={set('email')}/><Field label="Date of birth" type="date" value={form.dateOfBirth} onChange={set('dateOfBirth')}/><label className="space-y-1.5 text-sm font-medium text-slate-700"><span>Gender</span><select value={form.gender} onChange={set('gender')} className="w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5"><option value="">Not provided</option><option value="FEMALE">Female</option><option value="MALE">Male</option><option value="NON_BINARY">Non-binary</option><option value="PREFER_NOT_TO_SAY">Prefer not to say</option><option value="OTHER">Other</option></select></label></div><p className="text-xs text-slate-500">At least one contact method is required. Duplicate contact details are blocked within this practice.</p><div className="flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold">Cancel</button><button disabled={saving||(!form.mobile&&!form.email)} className="rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40">{saving?'Adding…':'Add client'}</button></div></form></div></div>}
